import { Visitor } from 'oxc-parser';
import { collectPropertyValues, findProperty, getImportMap } from '../../typescript/ast-helpers.js';
import { _parseFile } from '../../typescript/ast-nodes.js';
import { toEntryPath } from '../../util/input.js';
import { dirname } from '../../util/path.js';
import { _resolveSync } from '../../util/resolve.js';
export const resolveFromAST = (program, options) => {
    const entries = new Set();
    const addHandler = (specifier) => entries.add(specifier.substring(0, specifier.lastIndexOf('.')));
    const addHandlers = (values) => {
        for (const specifier of values)
            addHandler(specifier);
    };
    const parseImport = (specifier) => {
        const filePath = _resolveSync(specifier, dirname(options.configFilePath));
        const text = filePath ? options.readFile(filePath) : undefined;
        return filePath && text ? _parseFile(filePath, text).program : undefined;
    };
    try {
        const importMap = getImportMap(program);
        const dynamicImports = [];
        addHandlers(collectPropertyValues(program, 'handler'));
        const visitor = new Visitor({
            ImportExpression(node) {
                const source = node.source;
                if (source.type === 'Literal' && typeof source.value === 'string' && source.value.startsWith('.'))
                    dynamicImports.push(source.value);
            },
            CallExpression(node) {
                if (node.callee?.type !== 'MemberExpression')
                    return;
                const propName = !node.callee.computed ? node.callee.property?.name : undefined;
                if (propName === 'stack') {
                    const arg = node.arguments?.[0];
                    const importPath = arg?.type === 'Identifier' ? importMap.get(arg.name) : undefined;
                    const stack = importPath ? parseImport(importPath) : undefined;
                    if (stack)
                        addHandlers(collectPropertyValues(stack, 'handler'));
                }
                if (propName === 'route' && node.arguments?.length >= 2) {
                    const handlerArg = node.arguments[1];
                    if (handlerArg?.type === 'Literal' && typeof handlerArg.value === 'string')
                        addHandler(handlerArg.value);
                }
                if (propName === 'subscribe') {
                    const [first, second] = node.arguments;
                    const subscriber = second?.type === 'Literal'
                        ? second
                        : !second || (second.type === 'ObjectExpression' && !findProperty(second, 'handler'))
                            ? first
                            : undefined;
                    if (subscriber?.type === 'Literal' && typeof subscriber.value === 'string' && subscriber.value.includes('.'))
                        addHandler(subscriber.value);
                }
            },
        });
        visitor.visit(program);
        for (const infra of dynamicImports.map(parseImport)) {
            if (!infra)
                continue;
            addHandlers(collectPropertyValues(infra, 'handler'));
            visitor.visit(infra);
        }
    }
    catch { }
    return Array.from(entries).map(specifier => toEntryPath(specifier, { production: true }));
};
